import java.util.*;
class RiverMountainPreservationTest {
 public static void main(String[] args){int n=128;var e=new EnvironmentMap(new float[n*n]);e.water=EnvironmentMap.filled(n*n,62);e.river=new float[n*n];e.material=new byte[n*n];for(int z=0;z<n;z++)for(int x=0;x<n;x++)e.height[z*n+x]=100+Math.max(0,x-32)*2;for(int z=0;z<n;z++){int i=z*n+30;e.height[i]=96;e.water[i]=100;e.river[i]=1;}float[] original=e.height.clone();var node=new TerrainGraph.Node(1,TerrainGraph.Type.RIVER_BANKS,0,0);node.values.put("reach",100.0);node.values.put("width",8.0);node.values.put("courses",1.0);RiverBanks.gradeValley(node,e,n,n,62,71,0,0,()->false);for(int i=0;i<original.length;i++)if(original[i]-e.height[i]>4.001)throw new AssertionError("Valley grading excavates mountain");var before=e.height.clone();GroundSmoothing.apply(e,n,n,62,100,()->false);for(int i=0;i<original.length;i++){if(before[i]-e.height[i]>8.001)throw new AssertionError("Smoothing excavates mountain");if(e.water[i]!=62&&e.height[i]!=96)throw new AssertionError("Changed riverbed");}var routing=RiverCourse.route(original,e,n,n,62,()->false,false,1,71,.18);for(int i=0;i<original.length;i++){int p=routing.flow().parent()[i];if(p>=0&&original[p]>original[i]+.051)throw new AssertionError("River climbs ridge");}System.out.println("PASS: mountain slopes survive bank grading and repeated smoothing; routing cannot climb ridges");}
}
